import {
  forwardRef,
  useCallback,
  useEffect,
  useEffectEvent,
  useState,
  type ForwardedRef,
  type ReactNode,
} from 'react';
import {
  Animated,
  I18nManager,
  PanResponder,
  StyleSheet,
  useWindowDimensions,
  View,
  type GestureResponderEvent,
  type LayoutChangeEvent,
  type PanResponderGestureState,
  type Text,
  type TextProps,
  type ViewProps,
} from 'react-native';
import { useGlassTheme } from './glass-provider';
import { GlassSurface } from './glass-surface';
import {
  LAYER_EASING,
  ModalLayerClose,
  ModalLayerCloseButton,
  ModalLayerDescription,
  ModalLayerHost,
  ModalLayerRoot,
  ModalLayerScrim,
  ModalLayerTitle,
  ModalLayerTrigger,
  useLayerPresence,
  useModalLayer,
  useSafeInsets,
  type ModalLayerRootProps,
  type ModalLayerSlotProps,
} from './lib/modal-layer';
import { GLASS_MOTION } from './lib/tokens';

export type GlassSheetSide = 'top' | 'right' | 'bottom' | 'left';

export type GlassSheetProps = ModalLayerRootProps;

export type GlassSheetTriggerProps = ModalLayerSlotProps;

export type GlassSheetCloseProps = ModalLayerSlotProps;

export type GlassSheetContentProps = ViewProps & {
  children?: ReactNode;
  /** Names the close button for assistive tech. Defaults to "Close sheet". */
  closeLabel?: string;
  /**
   * The edge the sheet slides in from. Left and right follow the layout direction, so a left
   * sheet opens from the right in a right-to-left layout. Defaults to bottom.
   */
  side?: GlassSheetSide;
};

// The gap between the sheet and the screen's edges, and the panel's own padding.
const EDGE = 8;

const PAD = 24;

// A downward fling faster than this, in points per millisecond, dismisses the sheet.
const FLING_VELOCITY = 0.5;

// Where a drag of the grabber ended: its distance and its speed, in points per millisecond.
type GestureRelease = { dy: number; vy: number };

/** Holds a sheet's open state for its trigger, content and close controls. */
export function GlassSheet(props: GlassSheetProps) {
  return <ModalLayerRoot {...props} />;
}

/** Opens the sheet when its single child, such as a GlassButton, is pressed. */
export function GlassSheetTrigger({ children }: GlassSheetTriggerProps) {
  return (
    <ModalLayerTrigger component="GlassSheetTrigger" root="GlassSheet">
      {children}
    </ModalLayerTrigger>
  );
}

/** Closes the sheet when its single child is pressed. */
export function GlassSheetClose({ children }: GlassSheetCloseProps) {
  return (
    <ModalLayerClose component="GlassSheetClose" root="GlassSheet">
      {children}
    </ModalLayerClose>
  );
}

// Upward drags meet growing resistance instead of lifting the sheet off its edge.
function resist(distance: number) {
  return distance >= 0 ? distance : -Math.sqrt(-distance) * 2;
}

// Which way the sheet leaves: down and right are positive. A left sheet sits at the start edge.
function exitDirection(side: GlassSheetSide) {
  if (side === 'bottom') return 1;

  if (side === 'top') return -1;

  return (side === 'right') === !I18nManager.isRTL ? 1 : -1;
}

// Padding that keeps content clear of a safe-area inset the sheet's edge reaches into.
function clearOf(inset: number) {
  return Math.max(PAD, inset - EDGE);
}

type SheetLayerProps = GlassSheetContentProps & {
  onClose: () => void;
  onHidden: () => void;
  open: boolean;
  panelRef: ForwardedRef<View>;
  side: GlassSheetSide;
};

// Mounted while the sheet is on screen, so each opening measures the sheet afresh.
function SheetLayer({
  children,
  closeLabel = 'Close sheet',
  onClose,
  onHidden,
  open,
  panelRef,
  side,
  style,
  ...rest
}: SheetLayerProps) {
  const { colors, preferences } = useGlassTheme();
  const insets = useSafeInsets();
  const { height, width } = useWindowDimensions();
  const [progress] = useState(() => new Animated.Value(0));
  const [drag] = useState(() => new Animated.Value(0));
  const [extent, setExtent] = useState<number | null>(null);
  const [released, setReleased] = useState<GestureRelease | null>(null);
  const reduceMotion = preferences.reduceMotion;
  const vertical = side === 'top' || side === 'bottom';
  const measured = extent !== null;
  // Until the sheet has measured itself, a whole screen away keeps it out of sight.
  const travel = (extent ?? (vertical ? height : width)) + EDGE * 2;

  useEffect(() => {
    if (reduceMotion) {
      progress.setValue(1);
      drag.setValue(0);

      return;
    }

    if (!measured) {
      // Closed before it was laid out, so there is nothing on screen to slide away.
      if (!open) onHidden();

      return;
    }

    const slide = Animated.timing(progress, {
      duration: open ? 500 : 300,
      easing: LAYER_EASING.out,
      toValue: open ? 1 : 0,
      useNativeDriver: GLASS_MOTION.nativeDriver,
    });

    // Reopened while dropping away after a drag, the sheet springs back to its edge too. A new
    // drag stops only that spring, not the slide.
    const animation = open
      ? Animated.parallel(
          [
            slide,
            Animated.spring(drag, {
              ...GLASS_MOTION.spring,
              toValue: 0,
              useNativeDriver: GLASS_MOTION.nativeDriver,
            }),
          ],
          { stopTogether: false },
        )
      : slide;

    animation.start(({ finished }) => {
      if (finished && !open) onHidden();
    });

    return () => animation.stop();
  }, [drag, measured, onHidden, open, progress, reduceMotion]);

  // The responder is built once, so a re-render mid-drag cannot reset the gesture. It hands each
  // release to an effect, which reads the latest props.
  const [grabber] = useState(() => {
    const release = (_event: GestureResponderEvent, gesture: PanResponderGestureState) =>
      setReleased({ dy: gesture.dy, vy: gesture.vy });

    return PanResponder.create({
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: () => drag.stopAnimation(),
      onPanResponderMove: (_event, gesture) => drag.setValue(resist(gesture.dy)),
      onPanResponderRelease: release,
      onPanResponderTerminate: release,
      onPanResponderTerminationRequest: () => false,
      onStartShouldSetPanResponder: () => true,
    });
  });

  const settle = useEffectEvent(({ dy, vy }: GestureRelease) => {
    // The exit continues from where the finger let go.
    if (resist(dy) > Math.min(120, (extent ?? 0) * 0.25) || vy > FLING_VELOCITY) {
      onClose();

      return;
    }

    if (reduceMotion) {
      drag.setValue(0);

      return;
    }

    Animated.spring(drag, {
      ...GLASS_MOTION.spring,
      toValue: 0,
      useNativeDriver: GLASS_MOTION.nativeDriver,
    }).start();
  });

  useEffect(() => {
    if (released) settle(released);
  }, [released]);

  const handleLayout = (event: LayoutChangeEvent) => {
    const { height: sheetHeight, width: sheetWidth } = event.nativeEvent.layout;

    setExtent(vertical ? sheetHeight : sheetWidth);
  };

  const padding = {
    paddingBottom: side === 'top' ? PAD : clearOf(insets.bottom),
    paddingEnd: side === 'right' ? clearOf(insets.end) : PAD,
    paddingStart: side === 'left' ? clearOf(insets.start) : PAD,
    paddingTop: side === 'bottom' ? PAD : clearOf(insets.top),
  };

  // A sheet only moves along its own axis; only a bottom sheet is ever dragged.
  const offset = Animated.add(
    progress.interpolate({ inputRange: [0, 1], outputRange: [exitDirection(side) * travel, 0] }),
    drag,
  );

  return (
    <>
      <ModalLayerScrim onPress={onClose} progress={progress} />
      <View
        style={[
          { pointerEvents: 'box-none' },
          StyleSheet.absoluteFill,
          styles[side],
          vertical
            ? {
                paddingBottom: side === 'bottom' ? EDGE : insets.bottom + 40,
                paddingEnd: Math.max(EDGE, insets.end),
                paddingStart: Math.max(EDGE, insets.start),
                paddingTop: side === 'top' ? EDGE : insets.top + 40,
              }
            : styles.besideEdge,
        ]}
      >
        <Animated.View
          onLayout={handleLayout}
          style={[
            vertical ? styles.wideFrame : styles.tallFrame,
            { transform: vertical ? [{ translateY: offset }] : [{ translateX: offset }] },
          ]}
        >
          <GlassSurface
            ref={panelRef}
            accessibilityViewIsModal
            elevation="raised"
            onAccessibilityEscape={onClose}
            preset="overlay"
            style={[styles.panel, vertical ? styles.wide : styles.tall, padding, style]}
            {...rest}
          >
            {side === 'bottom' ? (
              <View {...grabber.panHandlers} style={styles.grabberZone}>
                <View style={[styles.grabber, { backgroundColor: colors.mutedForeground }]} />
              </View>
            ) : null}
            {children}
            <ModalLayerCloseButton
              label={closeLabel}
              onPress={onClose}
              style={{ end: padding.paddingEnd - EDGE, top: padding.paddingTop - EDGE }}
            />
          </GlassSurface>
        </Animated.View>
      </View>
    </>
  );
}

/** A modal glass panel that slides in from an edge; a bottom sheet drags down to dismiss. */
export const GlassSheetContent = forwardRef<View, GlassSheetContentProps>(
  ({ side = 'bottom', ...props }, ref) => {
    const { open, setOpen } = useModalLayer('GlassSheetContent', 'GlassSheet');
    const { preferences } = useGlassTheme();
    const [present, hide] = useLayerPresence(open, preferences.reduceMotion);
    const close = useCallback(() => setOpen(false), [setOpen]);

    return (
      <ModalLayerHost onRequestClose={close} present={present}>
        <SheetLayer
          {...props}
          onClose={close}
          onHidden={hide}
          open={open}
          panelRef={ref}
          side={side}
        />
      </ModalLayerHost>
    );
  },
);

GlassSheetContent.displayName = 'GlassSheetContent';

/** The sheet's heading, announced as a header. */
export const GlassSheetTitle = forwardRef<Text, TextProps>((props, ref) => (
  <ModalLayerTitle ref={ref} {...props} />
));

GlassSheetTitle.displayName = 'GlassSheetTitle';

/** The sheet's supporting text. */
export const GlassSheetDescription = forwardRef<Text, TextProps>((props, ref) => (
  <ModalLayerDescription ref={ref} {...props} />
));

GlassSheetDescription.displayName = 'GlassSheetDescription';

const styles = StyleSheet.create({
  besideEdge: { padding: EDGE },
  bottom: { alignItems: 'center', justifyContent: 'flex-end' },
  grabber: { borderRadius: 2.5, height: 5, opacity: 0.5, width: 36 },
  // A 44-point strip across the top of a bottom sheet; the panel's top padding sits under it.
  grabberZone: {
    alignItems: 'center',
    height: 44,
    justifyContent: 'center',
    marginHorizontal: -PAD,
    marginTop: -PAD,
  },
  left: { flexDirection: 'row', justifyContent: 'flex-start' },
  panel: { borderCurve: 'continuous', borderRadius: 40 },
  right: { flexDirection: 'row', justifyContent: 'flex-end' },
  tall: { flex: 1 },
  tallFrame: { maxWidth: 384, width: '100%' },
  top: { alignItems: 'center', justifyContent: 'flex-start' },
  wide: { flexShrink: 1 },
  wideFrame: { maxHeight: '100%', maxWidth: 640, width: '100%' },
});

import {
  Children,
  cloneElement,
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactElement,
  type ReactNode,
} from 'react';
import {
  Animated,
  Easing,
  I18nManager,
  Modal,
  Pressable,
  StyleSheet,
  Text,
  type AccessibilityState,
  type GestureResponderEvent,
  type ModalProps,
  type StyleProp,
  type TextProps,
  type ViewStyle,
} from 'react-native';
import { initialWindowMetrics, SafeAreaInsetsContext } from 'react-native-safe-area-context';
import { useGlassTheme } from '../glass-provider';
import { GlassIcon } from './icons';
import { useControllableState } from './use-controllable-state';

/** Arrivals ease out on the library's curve (`--lg-ease-out`); exits ease in. */
export const LAYER_EASING = {
  in: Easing.bezier(0.42, 0, 1, 1),
  out: Easing.bezier(0.32, 0.72, 0, 1),
};

/** The fill of a control on glass under a finger (`--lg-control-surface-hover`). */
export const CONTROL_SURFACE_PRESSED = {
  dark: 'rgba(245, 245, 247, 0.14)',
  light: 'rgba(255, 255, 255, 0.95)',
} as const;

// Without these, iOS turns a landscape screen back to portrait while a layer is open.
const ORIENTATIONS = [
  'portrait',
  'portrait-upside-down',
  'landscape',
  'landscape-left',
  'landscape-right',
] satisfies ModalProps['supportedOrientations'];

/**
 * The screen's safe-area insets, with start and end following the layout direction. Reads the
 * nearest SafeAreaProvider, or the window's first measurement when there is none.
 */
export function useSafeInsets() {
  const insets = useContext(SafeAreaInsetsContext) ?? initialWindowMetrics?.insets;
  const left = insets?.left ?? 0;
  const right = insets?.right ?? 0;

  return {
    bottom: insets?.bottom ?? 0,
    end: I18nManager.isRTL ? left : right,
    start: I18nManager.isRTL ? right : left,
    top: insets?.top ?? 0,
  };
}

/**
 * Whether a layer is on screen. It turns true with `open` and stays true until the layer calls
 * `hide` at the end of its exit, so the exit can play. Under Reduce Motion it turns false at once.
 */
export function useLayerPresence(open: boolean, reduceMotion: boolean) {
  const [present, setPresent] = useState(open);

  if (open && !present) setPresent(true);

  if (!open && present && reduceMotion) setPresent(false);

  const hide = useCallback(() => setPresent(false), []);

  return [present, hide] as const;
}

type ModalLayerState = {
  open: boolean;
  setOpen: (open: boolean) => void;
};

const ModalLayerContext = createContext<ModalLayerState | null>(null);

export type ModalLayerRootProps = {
  children?: ReactNode;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
};

/** Holds a modal layer's open state for its trigger, content and close controls. */
export function ModalLayerRoot({
  children,
  defaultOpen = false,
  onOpenChange,
  open,
}: ModalLayerRootProps) {
  const [current, setOpen] = useControllableState(open, defaultOpen, onOpenChange);
  const value = useMemo(() => ({ open: current, setOpen }), [current, setOpen]);

  return <ModalLayerContext.Provider value={value}>{children}</ModalLayerContext.Provider>;
}

/** The nearest modal layer's state. `component` and `root` name the parts in the error. */
export function useModalLayer(component: string, root: string) {
  const context = useContext(ModalLayerContext);

  if (!context) throw new Error(`${component} must be used within ${root}`);

  return context;
}

type PressableChildProps = {
  accessibilityState?: AccessibilityState;
  onPress?: ((event: GestureResponderEvent) => void) | null;
};

export type ModalLayerSlotProps = {
  /** One pressable element, such as a GlassButton. It keeps its own onPress. */
  children: ReactElement<PressableChildProps>;
};

type SlotOwnerProps = ModalLayerSlotProps & {
  component: string;
  root: string;
};

/** Gives its child an onPress that toggles the layer, and tells assistive tech whether it is open. */
export function ModalLayerTrigger({ children, component, root }: SlotOwnerProps) {
  const { open, setOpen } = useModalLayer(component, root);
  const child = Children.only(children);

  return cloneElement(child, {
    accessibilityState: { ...child.props.accessibilityState, expanded: open },
    onPress: (event: GestureResponderEvent) => {
      child.props.onPress?.(event);
      setOpen(!open);
    },
  });
}

/** Gives its child an onPress that closes the layer. */
export function ModalLayerClose({ children, component, root }: SlotOwnerProps) {
  const { setOpen } = useModalLayer(component, root);
  const child = Children.only(children);

  return cloneElement(child, {
    onPress: (event: GestureResponderEvent) => {
      child.props.onPress?.(event);
      setOpen(false);
    },
  });
}

type ModalLayerHostProps = {
  children: ReactNode;
  /** Android's back button and the web's Escape key. */
  onRequestClose: () => void;
  present: boolean;
};

/** React Native's Modal, set up for a layer that draws its own scrim and animates itself. */
export function ModalLayerHost({ children, onRequestClose, present }: ModalLayerHostProps) {
  return (
    <Modal
      animationType="none"
      navigationBarTranslucent
      onRequestClose={onRequestClose}
      statusBarTranslucent
      supportedOrientations={ORIENTATIONS}
      transparent
      visible={present}
    >
      {present ? children : null}
    </Modal>
  );
}

type ModalLayerScrimProps = {
  onPress: () => void;
  /** 0 hidden, 1 shown. */
  progress: Animated.Value;
};

/** The dimmed backdrop behind a modal layer. It fades with `progress`; a tap on it closes the layer. */
export function ModalLayerScrim({ onPress, progress }: ModalLayerScrimProps) {
  const { colors } = useGlassTheme();

  return (
    <>
      <Animated.View
        style={[
          { pointerEvents: 'none' },
          StyleSheet.absoluteFill,
          { backgroundColor: colors.scrim, opacity: progress },
        ]}
      />
      <Pressable
        accessible={false}
        importantForAccessibility="no"
        onPress={onPress}
        style={StyleSheet.absoluteFill}
      />
    </>
  );
}

type ModalLayerCloseButtonProps = {
  label: string;
  onPress: () => void;
  /** Places the button; it is absolutely positioned. */
  style?: StyleProp<ViewStyle>;
};

/** The round close button in a layer's top corner, with a 44-point target. */
export function ModalLayerCloseButton({ label, onPress, style }: ModalLayerCloseButtonProps) {
  const { colors, preferences } = useGlassTheme();

  return (
    <Pressable
      accessibilityLabel={label}
      accessibilityRole="button"
      hitSlop={4}
      onPress={onPress}
      style={({ pressed }) => [
        styles.close,
        {
          backgroundColor: pressed
            ? CONTROL_SURFACE_PRESSED[preferences.theme]
            : colors.controlSurface,
          borderColor: colors.border,
        },
        style,
      ]}
    >
      {({ pressed }) => (
        <GlassIcon
          color={pressed ? colors.foreground : colors.mutedForeground}
          name="close"
          size={16}
          strokeWidth={1.6}
        />
      )}
    </Pressable>
  );
}

/** A layer's heading, announced as a header and kept clear of the close button. */
export const ModalLayerTitle = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text
      ref={ref}
      accessibilityRole="header"
      style={[styles.title, { color: colors.foreground }, style]}
      {...rest}
    />
  );
});

ModalLayerTitle.displayName = 'ModalLayerTitle';

/** A layer's supporting text, in the muted ink. */
export const ModalLayerDescription = forwardRef<Text, TextProps>(({ style, ...rest }, ref) => {
  const { colors } = useGlassTheme();

  return (
    <Text
      ref={ref}
      style={[styles.description, { color: colors.mutedForeground }, style]}
      {...rest}
    />
  );
});

ModalLayerDescription.displayName = 'ModalLayerDescription';

const styles = StyleSheet.create({
  close: {
    alignItems: 'center',
    borderCurve: 'continuous',
    borderRadius: 18,
    borderWidth: 1,
    height: 36,
    justifyContent: 'center',
    position: 'absolute',
    width: 36,
  },
  description: { fontSize: 15, lineHeight: 21, marginTop: 6 },
  // The close button sits 16 points in from the corner; the title stops 8 points short of it.
  title: { fontSize: 20, fontWeight: '600', letterSpacing: -0.3, lineHeight: 25, paddingEnd: 36 },
});

import { View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type GlassIconName =
  | 'check'
  | 'chevron-down'
  | 'chevron-right'
  | 'close'
  | 'dash'
  | 'danger'
  | 'info'
  | 'success'
  | 'warning';

// The web components' own strokes, drawn on a 20-point grid.
const PATHS = {
  check: ['M4.5 10.5 8.25 14.25 15.5 6.25'],
  'chevron-down': ['M5 7.5l5 5 5-5'],
  'chevron-right': ['M7.5 4.4 13.1 10l-5.6 5.6'],
  close: ['M5.5 5.5l9 9m0-9l-9 9'],
  dash: ['M5 10h10'],
  danger: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M7.6 7.6l4.8 4.8', 'M12.4 7.6l-4.8 4.8'],
  info: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M10 9.2v4.1', 'M10 6.7h.01'],
  success: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M6.9 10.2l2.2 2.2 4-4.4'],
  warning: ['M10 3.6 17 16H3L10 3.6Z', 'M10 8.4v3.4', 'M10 14h.01'],
} as const satisfies Record<GlassIconName, readonly string[]>;

export type GlassIconProps = {
  color: string;
  name: GlassIconName;
  size?: number;
  strokeWidth?: number;
};

/** A stroked glyph from the library's small icon set. Decorative; label its control instead. */
export function GlassIcon({ color, name, size = 20, strokeWidth = 1.8 }: GlassIconProps) {
  // The hiding lives on a View: on the web, Svg passes its props to a bare <svg> element.
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{ height: size, width: size }}
    >
      <Svg width={size} height={size} viewBox="0 0 20 20" fill="none">
        {PATHS[name].map((path) => (
          <Path
            key={path}
            d={path}
            stroke={color}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={strokeWidth}
          />
        ))}
      </Svg>
    </View>
  );
}
